/**
 * An Issuing `Cardholder` object represents an individual or business entity who is [issued](https://stripe.com/docs/issuing) cards.
 * 
 * Related guide: [How to create a cardholder](https://stripe.com/docs/issuing/cards/virtual/issue-cards#create-cardholder)
 */
const IssuingCardholder = z.object({
'billing': IssuingCardholderAddress,
'company': z.union([IssuingCardholderCompany]).optional(),
'created': z.number().int(),
'email': z.string().nullable().optional(),
'id': z.string(),
'individual': z.union([IssuingCardholderIndividual]).optional(),
'livemode': z.boolean(),
'metadata': z.record(z.string(), z.string()),
'name': z.string(),
'object': z.enum(['issuing.cardholder']),
'phone_number': z.string().nullable().optional(),
'preferred_locales': z.array(z.enum(['de', 'en', 'es', 'fr', 'it'])).nullable().optional(),
'requirements': IssuingCardholderRequirements,
'spending_controls': z.union([IssuingCardholderAuthorizationControls]).optional(),
'status': z.enum(['active', 'blocked', 'inactive']),
'type': z.enum(['company', 'individual'])
});

export const parseIssuingCardholder = (value) => IssuingCardholder.parse(value);

const IssuingCardFraudWarning = z.object({
'started_at': z.number().int().nullable().optional(),
'type': z.enum(['card_testing_exposure', 'fraud_dispute_filed', 'third_party_reported', 'user_indicated_fraud']).nullable().optional()
});

export const parseIssuingCardFraudWarning = (value) => IssuingCardFraudWarning.parse(value);

const IssuingPersonalizationDesignCarrierText = z.object({
'footer_body': z.string().nullable().optional(),
'footer_title': z.string().nullable().optional(),
'header_body': z.string().nullable().optional(),
'header_title': z.string().nullable().optional()
});

export const parseIssuingPersonalizationDesignCarrierText = (value) => IssuingPersonalizationDesignCarrierText.parse(value);

const IssuingPhysicalBundleFeatures = z.object({
'card_logo': z.enum(['optional', 'required', 'unsupported']),
'carrier_text': z.enum(['optional', 'required', 'unsupported']),
'second_line': z.enum(['optional', 'required', 'unsupported'])
});

export const parseIssuingPhysicalBundleFeatures = (value) => IssuingPhysicalBundleFeatures.parse(value);

/**
 * A Physical Bundle represents the bundle of physical items - card stock, carrier letter, and envelope - that is shipped to a cardholder when you create a physical card.
 */
const IssuingPhysicalBundle = z.object({
'features': IssuingPhysicalBundleFeatures,
'id': z.string(),
'livemode': z.boolean(),
'name': z.string(),
'object': z.enum(['issuing.physical_bundle']),
'status': z.enum(['active', 'inactive', 'review']),
'type': z.enum(['custom', 'standard'])
});

export const parseIssuingPhysicalBundle = (value) => IssuingPhysicalBundle.parse(value);

const IssuingPersonalizationDesignPreferences = z.object({
'is_default': z.boolean(),
'is_platform_default': z.boolean().nullable().optional()
});

export const parseIssuingPersonalizationDesignPreferences = (value) => IssuingPersonalizationDesignPreferences.parse(value);

const IssuingPersonalizationDesignRejectionReasons = z.object({
'card_logo': z.array(z.enum(['geographic_location', 'inappropriate', 'network_name', 'non_binary_image', 'non_fiat_currency', 'other', 'other_entity', 'promotional_material'])).nullable().optional(),
'carrier_text': z.array(z.enum(['geographic_location', 'inappropriate', 'network_name', 'non_fiat_currency', 'other', 'other_entity', 'promotional_material'])).nullable().optional()
});

export const parseIssuingPersonalizationDesignRejectionReasons = (value) => IssuingPersonalizationDesignRejectionReasons.parse(value);

/**
 * A Personalization Design is a logical grouping of a Physical Bundle, card logo, and carrier text that represents a product line.
 */
const IssuingPersonalizationDesign = z.object({
'card_logo': z.union([z.string(), z.lazy(() => File)]).optional(),
'carrier_text': z.union([IssuingPersonalizationDesignCarrierText]).optional(),
'created': z.number().int(),
'id': z.string(),
'livemode': z.boolean(),
'lookup_key': z.string().nullable().optional(),
'metadata': z.record(z.string(), z.string()),
'name': z.string().nullable().optional(),
'object': z.enum(['issuing.personalization_design']),
'physical_bundle': z.union([z.string(), IssuingPhysicalBundle]),
'preferences': IssuingPersonalizationDesignPreferences,
'rejection_reasons': IssuingPersonalizationDesignRejectionReasons,
'status': z.enum(['active', 'inactive', 'rejected', 'review'])
});

export const parseIssuingPersonalizationDesign = (value) => IssuingPersonalizationDesign.parse(value);

const IssuingCardShippingAddressValidation = z.object({
'mode': z.enum(['disabled', 'normalization_only', 'validation_and_normalization']),
'normalized_address': z.union([Address]).optional(),
'result': z.enum(['indeterminate', 'likely_deliverable', 'likely_undeliverable']).nullable().optional()
});

export const parseIssuingCardShippingAddressValidation = (value) => IssuingCardShippingAddressValidation.parse(value);

const IssuingCardShippingCustoms = z.object({
'eori_number': z.string().nullable().optional()
});

export const parseIssuingCardShippingCustoms = (value) => IssuingCardShippingCustoms.parse(value);

const IssuingCardShipping = z.object({
'address': Address,
'address_validation': z.union([IssuingCardShippingAddressValidation]).optional(),
'carrier': z.enum(['dhl', 'fedex', 'royal_mail', 'usps']).nullable().optional(),
'customs': z.union([IssuingCardShippingCustoms]).optional(),
'eta': z.number().int().nullable().optional(),
'name': z.string(),
'phone_number': z.string().nullable().optional(),
'require_signature': z.boolean().nullable().optional(),
'service': z.enum(['express', 'priority', 'standard']),
'status': z.enum(['canceled', 'delivered', 'failure', 'pending', 'returned', 'shipped', 'submitted']).nullable().optional(),
'tracking_number': z.string().nullable().optional(),
'tracking_url': z.string().nullable().optional(),
'type': z.enum(['bulk', 'individual'])
});

export const parseIssuingCardShipping = (value) => IssuingCardShipping.parse(value);

